#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

/* PDF Generation Service - Kubernetes Pod
 * Each tenant has isolated document storage.
 * Authorization is enforced via tenant_id from the K8s service mesh sidecar.
 */

#define MAX_TENANTS 256
#define MAX_DOCS_PER_TENANT 1024
#define DOC_ID_LEN 32
#define TENANT_HEADER_KEY "X-Mesh-Tenant-Id"

typedef struct {
    char doc_id[DOC_ID_LEN];
    uint32_t owner_tenant;
    size_t pdf_size;
    unsigned char *pdf_data;
    int generation_complete;
} pdf_document_t;

typedef struct {
    uint32_t tenant_id;
    pdf_document_t *documents[MAX_DOCS_PER_TENANT];
    int doc_count;
    pthread_mutex_t lock;
} tenant_store_t;

static tenant_store_t g_stores[MAX_TENANTS];
static pthread_rwlock_t g_catalog_lock = PTHREAD_RWLOCK_INITIALIZER;

typedef struct {
    char doc_id[DOC_ID_LEN];
    uint32_t resolved_tenant;
    int store_index;
    int doc_index;
} doc_lookup_result_t;

/* Resolve document location across all tenant stores.
 * Used internally for cross-tenant operations (e.g., shared templates).
 * Returns 0 on success, -1 if not found.
 */
static int catalog_resolve_document(const char *doc_id, doc_lookup_result_t *result) {
    pthread_rwlock_rdlock(&g_catalog_lock);
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (g_stores[i].tenant_id == 0) continue;
        pthread_mutex_lock(&g_stores[i].lock);
        for (int j = 0; j < g_stores[i].doc_count; j++) {
            if (g_stores[i].documents[j] &&
                strncmp(g_stores[i].documents[j]->doc_id, doc_id, DOC_ID_LEN) == 0) {
                strncpy(result->doc_id, doc_id, DOC_ID_LEN - 1);
                result->doc_id[DOC_ID_LEN - 1] = '\0';
                result->resolved_tenant = g_stores[i].tenant_id;
                result->store_index = i;
                result->doc_index = j;
                pthread_mutex_unlock(&g_stores[i].lock);
                pthread_rwlock_unlock(&g_catalog_lock);
                return 0;
            }
        }
        pthread_mutex_unlock(&g_stores[i].lock);
    }
    pthread_rwlock_unlock(&g_catalog_lock);
    return -1;
}

/* Authorization check: verify requesting tenant owns the document.
 * The sidecar injects tenant_id; we compare against document ownership.
 */
static int authorize_document_access(uint32_t requesting_tenant,
                                      const doc_lookup_result_t *lookup) {
    /* Template documents (owner_tenant == 0) are accessible to all */
    pdf_document_t *doc = g_stores[lookup->store_index].documents[lookup->doc_index];
    if (doc->owner_tenant == 0) return 1;

    /* Check tenant match using actual document owner */
    return (doc->owner_tenant == requesting_tenant) ? 1 : 0;
}

/* Fetch PDF content after authorization */
static int fetch_pdf_content(uint32_t requesting_tenant, const char *doc_id,
                             unsigned char **out_buf, size_t *out_size) {
    doc_lookup_result_t lookup;
    memset(&lookup, 0, sizeof(lookup));

    if (catalog_resolve_document(doc_id, &lookup) != 0) {
        return -1; /* Document not found */
    }

    if (!authorize_document_access(requesting_tenant, &lookup)) {
        return -2; /* Access denied */
    }

    /* Retrieve the document data */
    pthread_mutex_lock(&g_stores[lookup.store_index].lock);
    pdf_document_t *doc = g_stores[lookup.store_index].documents[lookup.doc_index];
    if (doc && doc->generation_complete) {
        *out_buf = malloc(doc->pdf_size);
        if (*out_buf) {
            memcpy(*out_buf, doc->pdf_data, doc->pdf_size);
            *out_size = doc->pdf_size;
            pthread_mutex_unlock(&g_stores[lookup.store_index].lock);
            return 0;
        }
        /* Allocation failed: report error instead of a bogus success */
        *out_size = 0;
        pthread_mutex_unlock(&g_stores[lookup.store_index].lock);
        return -5;
    }
    pthread_mutex_unlock(&g_stores[lookup.store_index].lock);
    return -3; /* Not ready */
}

/* PDF generation callback - runs asynchronously */
static void *generate_pdf_worker(void *arg) {
    pdf_document_t *doc = (pdf_document_t *)arg;
    /* Simulate PDF generation */
    doc->pdf_size = 4096;
    doc->pdf_data = malloc(doc->pdf_size);
    if (doc->pdf_data) {
        memset(doc->pdf_data, 0, doc->pdf_size);
        /* Write PDF header */
        memcpy(doc->pdf_data, "%PDF-1.4\n", 9);
    }
    __sync_synchronize();
    doc->generation_complete = 1;
    return NULL;
}

/* Create a new PDF document for a tenant */
static int create_pdf_document(uint32_t tenant_id, const char *doc_id,
                               const char *template_id) {
    int store_idx = -1;

    pthread_rwlock_wrlock(&g_catalog_lock);
    for (int i = 0; i < MAX_TENANTS; i++) {
        if (g_stores[i].tenant_id == tenant_id) {
            store_idx = i;
            break;
        }
        if (g_stores[i].tenant_id == 0 && store_idx == -1) {
            store_idx = i;
        }
    }

    if (store_idx == -1) {
        pthread_rwlock_unlock(&g_catalog_lock);
        return -1;
    }

    if (g_stores[store_idx].tenant_id == 0) {
        g_stores[store_idx].tenant_id = tenant_id;
        pthread_mutex_init(&g_stores[store_idx].lock, NULL);
    }
    pthread_rwlock_unlock(&g_catalog_lock);

    pthread_mutex_lock(&g_stores[store_idx].lock);
    int idx = g_stores[store_idx].doc_count;
    if (idx >= MAX_DOCS_PER_TENANT) {
        pthread_mutex_unlock(&g_stores[store_idx].lock);
        return -2;
    }

    pdf_document_t *doc = calloc(1, sizeof(pdf_document_t));
    if (!doc) {
        pthread_mutex_unlock(&g_stores[store_idx].lock);
        return -3;
    }

    strncpy(doc->doc_id, doc_id, DOC_ID_LEN - 1);
    doc->doc_id[DOC_ID_LEN - 1] = '\0';
    doc->owner_tenant = tenant_id;
    doc->generation_complete = 0;

    g_stores[store_idx].documents[idx] = doc;
    g_stores[store_idx].doc_count++;
    pthread_mutex_unlock(&g_stores[store_idx].lock);

    /* Start async PDF generation */
    pthread_t worker;
    pthread_create(&worker, NULL, generate_pdf_worker, doc);
    pthread_detach(worker);

    return 0;
}

/* HTTP request handler - called by the service mesh */
typedef struct {
    uint32_t tenant_id;  /* Extracted from X-Mesh-Tenant-Id header */
    char method[8];
    char path[256];
    char doc_id[DOC_ID_LEN];
    char template_id[DOC_ID_LEN];
} http_request_t;

int handle_request(const http_request_t *req, unsigned char **response, size_t *resp_size) {
    if (strcmp(req->method, "GET") == 0) {
        return fetch_pdf_content(req->tenant_id, req->doc_id, response, resp_size);
    } else if (strcmp(req->method, "POST") == 0) {
        return create_pdf_document(req->tenant_id, req->doc_id, req->template_id);
    }
    return -4;
}
